P=pathlib.Path('/Users/imb/Documents/Codex/Analisi-statistica-Xee/runs/20261029_background_validation');summ=json.loads((P/'toy_summary.json').read_text());rows=list(csv.DictReader((P/'toys_effective.csv').open()));initial=list(csv.DictReader((P/'toys_all.csv').open()));observed=json.loads((P/'observed_comparison.json').read_text())
